# Every row is an authored shot: DE/EN starts, mode, set, title, action, camera, transition.
SHOTS = [
 (0,0,'3D','room','Das einzige helle Fenster','Eine schlafende Häuserfront. Hinter einem einzigen Fenster bewegen sich die vier Spuren einer Sequencer-Demo. Die Kamera findet den Arbeitsplatz; die Person sitzt bereits dort. Eine offene Änderungsnotiz ist der einzige unerledigte Punkt.','Langsame Fahrt von der Fassade durch das offene Fenster, 35 mm; am Ende über der rechten Schulter.','Die rechteckige Fensteröffnung wird zum Monitorrahmen.'),
 (9.18,12.68,'2D','screen','Eine winzige Bitte','Die Notiz öffnet sich: „Nur ein Regler“ / „Just one slider“. Daneben steht ein fertig getesteter Stand. Der Cursor zieht die Notiz in das Promptfeld; der fertige Stand bleibt sichtbar.','Orthogonal, keinerlei Perspektivverzerrung. Zwei grosse Flächen, eine eindeutige Cursorbewegung.','Match Cut: Notizrand auf Eingabefeld.'),
 (13.14,16.64,'3D','desk','Gleich Schluss','Die Hand rückt zur Kante des Laptops, als würde sie zuklappen wollen. Die Kamera hält den dünnen Spalt zwischen Display und Tastatur. Der Bildschirm bleibt offen.','85-mm-Detail seitlich, sehr geringe Fahrt; Hand und Scharnier bleiben klar lesbar.','Kurzer Dunkelimpuls folgt der gemessenen Pegeländerung der jeweiligen Fassung.'),
 (14.3,17.9,'3D','desk','Der Rückweg zur Taste','Vom Scharnier gleitet die Kamera flach über die Tastatur zur Sendetaste. Die Hand kehrt zurück. Auf dem Display erscheint der erste Auftrag P01; der erste kleine Arbeitsschritt wird in Gang gesetzt.','24-mm-Makrofahrt knapp über den Tasten, kein Flug durch Geometrie.','Rechteck der Sendetaste auf den ersten Pattern-Schritt.'),
 (21,28,'2D','screen','Vier Spuren, ein Projekt','Die Demo stellt sich selbst vor: vier Reihen, sechzehn Schritte. Ein Regler bekommt seinen Platz, der Playhead läuft. Drei Projektstände liegen als kleine Vorher-/Nachher-Karten darunter.','Statische Aufsicht; zuerst Gesamtraster, dann ein klarer Ausschnitt.','Die Kartenkante klappt in eine räumliche Ebene.'),
 (25,38.5,'hybrid','project','Erster Blick in die Tiefe','Dieselbe Oberfläche staffelt sich in drei lesbare Ebenen: Auftrag, Änderung, laufende Vorschau. Der Blick fährt hindurch und landet wieder am echten Monitor. Die längere EN-Passage zeigt zusätzlich Save und Reload als stumme Vorwegnahme des späteren Tests.','Perspektive 35 mm mit sanfter Parallaxe; pro Variante eigener Fahrtweg und Haltepunkt.','Rückkehr in identische Monitorposition, dann Blick zur Uhr.'),
 (28.56,45.24,'3D','desk','01:00','Die Schreibtischuhr zeigt 01:00. Im selben Bild leuchtet der fertige Build grün. Ein Finger tippt neben die Uhr: Es ist noch Zeit.','50-mm-Seitenansicht, Uhr vorne links, Build-Anzeige hinten rechts; kurzer Fokuswechsel.','Die grüne Statuskante wird zum Rand einer neuen Karte.'),
 (32.2,49.54,'2D','screen','Noch eine Idee','Eine einzige neue Funktionskarte schiebt den bisherigen Abschluss zur Seite. Die Demo bleibt dieselbe; ergänzt wird ein Regler für die vorhandene Bassspur.','Feste Bildschirmansicht mit Platz für genau eine neue Karte.','Die runde Reglerfläche füllt den nächsten Ausschnitt.'),
 (35.7,52.86,'2D','screen','Der zweite Klang','Ein Regler bewegt sich. In der zweiten aktiven Spur gehen vier Schritte an; daneben bleibt die ursprüngliche Spur sichtbar. Die Aktion erzeugt einen überprüfbaren Unterschied zwischen den zwei Projektständen.','Aufsicht auf das 4×16-Raster; eine kontrollierte Vergrösserung zum betroffenen Bereich.','Auf leeren Raum rechts schneiden; dort wächst der nächste Auftrag.'),
 (39.2,56.58,'hybrid','project','Der Prompt wird länger','Das neue Promptfeld erweitert sich um zwei konkrete Anforderungen: speichern und nach Reload wiederherstellen. Die Karte schiebt die ältere räumlich nach hinten; Kontext ist als Stapel nachvollziehbarer Aufträge sichtbar.','Seitliche 50-mm-Fahrt an drei beschrifteten Flächen; Textflächen drehen erst nach ihrer Lesezeit.','Die Vorderseite der obersten Karte wird wieder zum flachen Browser.'),
 (42.8,60.2,'2D','screen','Reload. Bassspur leer.','Der Reload-Test läuft. Kick, Snare und Hats bleiben gespeichert; nur die Bassreihe ist leer. Ein kleiner Meter mit der Beschriftung „BASS PREVIEW“ bleibt unten. Das Problem wird sofort lokalisiert.','Unbewegte Nahsicht: Reload oben, leere vierte Reihe unten. Kein Rot auf dem ganzen Bildschirm.','Die leere Bassreihe zieht als Umriss in den Codevergleich.'),
 (46.26,63.64,'2D','screen','Die fehlende Zeile','Links fehlt beim Laden die Zuweisung der Bassspur. Rechts ergänzt der Agent genau diese Zuweisung. Ein Verbindungspfad zeigt gespeichertes Basspattern → geladene Bassspur.','Drei grosse, ruhige Elemente: Speicherwert, eine Diff-Zeile, Pattern.','Die neue Codezeile schiebt die Bassreihe zurück ins Raster.'),
 (49.82,67.18,'3D','project','Derselbe Test besteht','Die zuvor leere Bassreihe enthält wieder ihre vier Schritte. Die Kamera steht jetzt schräg vor dem als flachem Modell dargestellten Raster. Save → Reload → Compare wird einmal vollständig durchlaufen; erst danach erscheint PASS.','35-mm-Dolly entlang derselben vier Basszellen; deutlich erkennbare Vorher-/Nachher-Positionen.','Ein grüner PASS-Rahmen wird zur Kontur der Uhr.'),
 (52.92,70.66,'3D','desk','02:00','Zurück am Tisch: dieselbe Uhr zeigt 02:00. Die Hand lässt die Bildschirmkante los und greift wieder zur Tastatur. Die vorherige Notiz ist erledigt; eine neue liegt bereit.','Langsame Rückfahrt von Uhr zu Hand, 50 mm; kein neuer Raum.','Die Rückfahrt setzt sich in der Instrumentalpassage fort.'),
 (56.56,74.5,'3D','room','Erster Erfolg','Eine halbe Umkreisung zeigt den ganzen Arbeitsplatz. Die Demo läuft; der Kaffeebecher steht noch voll daneben. In der Monitorreflexion gleitet bereits die nächste Idee ins Bild.','Einmalige 120°-Fahrt, Radius 1,4 m; anschliessend kurzer Halt über der Schulter.','Reflexion und Bildschirmfläche decken sich.'),
 (63.04,81.32,'2D','screen','Raus und rein','Der Auftrag P03 verlässt links das Eingabefeld. Rechts entstehen Antwort, Änderung und Testresultat in dieser Reihenfolge. Kleine IN- und OUT-Zahlen gehören sichtbar zu diesem Auftrag.','Zwei Spalten mit einer gemeinsamen horizontalen Achse; keine laufende Textwand.','Die Antwort endet, aber unter ihr bleibt eine neue Frage offen.'),
 (66.62,84.82,'3D','desk','Der freie Platz','Der Cursor fährt kurz zum Schliessen-Knopf. Daneben entsteht eine freie Funktionsfläche; die Hand entscheidet sich für das Eingabefeld. Der Stuhl rollt wenige Zentimeter näher an den Tisch.','Seitliche 70-mm-Nahaufnahme auf Hand, Trackpad und unteren Monitorrand.','Eine vertikale Monitorlinie zieht ins nächste Bild.'),
 (70.1,88.3,'hybrid','project','Weniger Nacht, mehr Text','Links wandert ein Lichtstreifen am Fenster. Rechts wächst der Auftragstapel um bereits bekannte Anforderungen. Beide Bewegungen laufen gegeneinander; die Uhr bleibt die zeitliche Referenz.','Ruhige symmetrische Komposition: reales Fenster und schematische Projektflächen. EN-Schnitt ist redaktionell, keine ergänzte Lyric-Zeit.','Die Karten ziehen auf eine gemeinsame Frontalebene.'),
 (73.7,91.88,'2D','screen','Die Sekunde vor dem Titel','Alles ordnet sich. Der Cursor blinkt einmal, die Demo bleibt sichtbar, und der Nutzungsstreifen sammelt sich als schmale orange Linie am unteren Rand. Der Titel wird noch zurückgehalten.','Zentral und nahezu still; keine Kamerapumpe vor dem Einsatz.','Harter Schnitt auf H01, an der tatsächlichen Stimme verankert.'),
 (78.66,96.48,'2D','type','H01 · TOKEN BURN','TOKEN steht weiss, BURN orange, beide gross in zwei Zeilen. Die Buchstaben kommen als ein zusammenhängender Schlag ins Bild. In ihren Flächen läuft für einen Moment das bekannte Pattern weiter.','Frontal; Schrift bis 72 % Bildbreite, anschliessend mindestens 0,9 s ruhig lesbar.','Die untere BURN-Kante wird zum Promptfeld.'),
 (82.56,99.86,'2D','screen','Noch ein Prompt','Das Titelgewicht bleibt in der Komposition: Darunter steht eine einzige neue Eingabe. Auf „noch ein“ / „one more“ rastet eine zusätzliche Auftragskarte ein. Die neue Karte verdeckt den Feierabend-Knopf.','Feste Mittelachse; kurzer horizontaler Einschub mit klarer Endposition.','Ein Kartenrahmen wird zum Umriss des zweiten Titelbilds.'),
 (85.74,103.52,'hybrid','type','H02 · Hinter dem Wort','TOKEN BURN kehrt als dieselbe klare Kontur zurück. Nach der Lesepause erhält die Schrift eine geringe Tiefe; die Kamera fährt an der rechten Kante vorbei zur laufenden Demo dahinter.','Erst frontal, danach höchstens 15° Schrägsicht. Keine unlesbare Fahrt durch Buchstaben.','Kontur deckungsgleich mit Monitorrahmen; Rückkehr zur Handlung.'),
 (89.14,106.9,'2D','screen','Den nächsten Stand sehen','Ein neuer Build wird neben dem vorigen Stand geöffnet. Genau ein zusätzlicher Regler ist sichtbar. Der Blick darf den Unterschied erkennen; der Bildinhalt trägt die Szene auch bei der unsicheren DE-Zeile.','Zwei ruhige Ansichten, identisches Raster und identischer Zoom.','Die beiden Ansichten werden zu Browser-Tabs.'),
 (92.7,110.82,'2D','screen','Minus eins, plus zwei','Ein Browser-Tab schliesst sich. Zwei neue öffnen sich: Vorschau und Export. Die Anzahl erhöht sich sichtbar um eins. Der Nutzungszähler bleibt bestehen.','Horizontale Tab-Leiste, grosse Namen, keine winzigen Browserdetails.','Der zweite neue Tab kippt als Karte auf den Schreibtisch.'),
 (96.16,114.34,'3D','desk','Dieser eine','Neben dem Laptop liegt eine einzelne Karte: Export. Alle erledigten Karten sind ordentlich gestapelt. Die Hand zieht genau diese letzte Karte wieder vor sich.','70-mm-Detail, Hand kommt aus derselben Bildseite wie zuvor.','Kartenecke als Match Cut in die folgende Kreisfahrt.'),
 (100.84,117,'3D','project','Der Stand von eben','Die Kamera umkreist drei gespeicherte Projektstände. Das erste kleine Pattern, der ergänzte Regler und die reparierte Bassspur sind gleichzeitig erkennbar. Fortschritt wird räumlich sichtbar.','Langsame Kreisbahn mit klarer Vorderseite der Versionen; eine einzige kontinuierliche Fahrt.','Die Kamera steigt zur Aufsicht.'),
 (107.9,120.1,'2D','screen','Der nächste freie Slot','In der Aufsicht werden die drei Stände zu drei nebeneinanderliegenden Karten. Rechts erscheint ein leerer vierter Slot. Der Cursor fährt genau dorthin. In der kürzeren EN-Passage nur dieser eine Vorgang.','Orthogonal, ruhige horizontale Bewegung.','Der leere Slot schneidet auf die Uhr.'),
 (115.08,123.32,'3D','room','03:00','Die Uhr steht auf 03:00. Die Totale zeigt dieselben Raumgrenzen, denselben Stuhl und dieselbe Person. Das Projekt ist gewachsen, der Raum nicht.','Weite 28-mm-Totale vom Fenster zum Tisch; keine übertriebene Weitwinkelverzerrung.','Gerader Vorstoss auf den Monitor.'),
 (118.68,128.88,'hybrid','project','Mehr Platz auf dem Screen','Der Monitor öffnet sich zu einer übersichtlichen Projektansicht mit Versionen, Vorschau und Export. Nur die Darstellung wird räumlich auseinandergezogen; der Schreibtisch bleibt als Referenz im unteren Bild.','35-mm-Vorwärtsfahrt, die auf eine orthogonale Übersicht übergeht.','Der Exportbereich wächst zur Vollbildfläche.'),
 (122.16,132.4,'2D','screen','Der Export fehlt','DE: Der Exportknopf ist noch nicht bereit. EN: Ein Versuch endet mit FAILED. Beide Fassungen zeigen anschliessend dieselbe konkrete Ursache: Der Bassbereich fehlt im Exportdatenmodell.','Zwei grosse Blöcke: vier Spuren links, drei exportierte Spuren rechts; fehlende Basszeile als Leerraum.','Der Leerraum zieht den Blick zur Antwort des Agenten.'),
 (125.48,135.88,'2D','screen','Eine gezielte Reparatur','Der Agent nimmt die fehlende Bassspur in den Export auf. Vier Eingabespuren stehen vier exportierten Spuren gegenüber. Der Vergleich prüft dieselben 64 Schritte; dann erst wird die Datei als fertig angezeigt.','Statische geteilte Ansicht; zuerst Änderung, dann Test, dann Ergebnis.','Die abgeschlossene Auftragskarte schiebt sich in das Nutzungsjournal.'),
 (128.58,139.42,'2D','ledger','Was die Session verbraucht','Das Nutzungsjournal zeigt Aufträge mit getrennten IN-/OUT-Werten und eine laufende Summe. Darunter stehen Kosten in fiktiven Demo-Credits. Der neue Eintrag ist die gerade abgeschlossene Arbeit, kein beatgesteuerter Fantasiezähler.','Frontal, drei klar ausgerichtete Zahlenkolonnen, die älteren Aufträge verblassen leicht.','Die Zeitspalte wird zur Schreibtischuhr.'),
 (132.1,142.94,'3D','desk','Die Zeit liegt daneben','Die Kamera zeigt Uhr, Kaffeetasse und den neuen Export in einer ruhigen Diagonale. Neben dem erledigten Auftrag liegt schon die nächste Notiz. Der Cursor bleibt in deren Nähe.','50-mm-Fahrt von der Uhr über die Tasse zum Monitor; Motive bleiben im gleichen Raum.','Blickanschluss zum Schliessen-Knopf.'),
 (135.96,146.48,'2D','screen','Speichern, dann gehen','Save wird bestätigt. Der Cursor hält über Schliessen. Die fertige Demo und die Exportdatei sind vollständig sichtbar. Der nächste Auftrag steht bereits in einer zweiten Zeile, ohne abgesendet zu sein.','Unbewegtes Bild mit einer auffälligen Pause in der Cursorbewegung.','Die zweite Zeile erhält Fokus und verdrängt den Abschluss.'),
 (139.88,149.62,'hybrid','project','Ein weiterer Auftrag','Die Eingabe wird aktiviert. Ein leerer Antwortbereich öffnet sich hinter ihr. Die Kamera beginnt sich abzusenken; die zweite Refrainrunde bekommt erstmals eine deutlich tiefere Perspektive.','Kurze Absenkung von Bildschirmhöhe zur Tischkante; Blick bleibt auf derselben Karte.','DE: kurzer Energieeinbruch um 141,9 s, dann H03; EN folgt eigenem Einsatz.'),
 (142.26,153,'3D','type','H03 · Die Dimension wächst','TOKEN BURN steht als kompakte, flache 3D-Schrift vor dem Schreibtisch. Der orange Nutzungsstreifen setzt sich unter den Buchstaben fort. Die Schrift verdeckt kurz den Monitor, danach wird das gewachsene Projekt dahinter sichtbar.','Tiefe 35-mm-Sicht, Schrift frontal lesbar; kleiner Dolly zurück statt Orbit.','Die Unterkante der Schrift wird zum Auftragsjournal.'),
 (145.82,156.14,'2D','ledger','Einer passt noch','Im Journal schiebt sich eine neue Auftragszeile ein. Die älteren Zeilen bleiben erhalten. „NOCH EIN PROMPT“ / „ONE MORE PROMPT“ steht kurz als klare Zwischenüberschrift über der neuen Zeile.','Feste Aufsicht, rhythmischer Einschub; keine Zahl läuft ohne zugehörigen Auftrag.','Der neue Zeilenrand streckt sich zum nächsten Titel.'),
 (149.42,159.8,'hybrid','type','H04 · Der Titel wird ein Raumteiler','Ein zweiter TOKEN-BURN-Schlag teilt das Bild vertikal: links Eingabe, rechts Ergebnis. Nach der Lesepause zieht die Kamera seitlich an der Schrift vorbei und verbindet beide Flächen wieder.','Erst orthogonal, danach kurze seitliche 40-mm-Fahrt. DE-Anker ist ein unsicheres ASR-Unterfenster und bleibt markiert.','Die zwei Flächen werden zum Vorher-/Nachher-Vergleich.'),
 (152.6,163.18,'2D','screen','Das Resultat','Der neue Stand enthält Export plus gespeicherte Einstellungen. Ein einzelner Vergleich bestätigt die Änderung. Der Film hält lange genug, um das Ergebnis zu verstehen.','Frontaler Vergleich in derselben Geometrie wie S023, jetzt mit erweitertem Inhalt.','Die beiden Vergleichskarten rücken nach oben in die Tab-Leiste.'),
 (156.16,166.9,'3D','project','Tabs mit Geschichte','Die Tab-Karten stehen nun räumlich hintereinander. Eine schliesst sich, zwei kommen hinzu. Ihre Vorschaubilder zeigen echte frühere Zustände dieser Demo; keine zufälligen Fenster.','Seitlicher 50-mm-Tracking-Shot entlang der Kartenreihe; neue Karten bleiben vorne.','Vorderste Karte fährt deckungsgleich auf den Tisch.'),
 (159.68,170.58,'3D','desk','Die Hand bleibt','Die Hand liegt an der Laptopkante, zieht sich zurück und greift erneut zum Trackpad. Die Kamera fährt in die Gegenrichtung zum ersten Refrain: diesmal näher heran.','70-mm-Nahfahrt auf Hand und Scharnier, dann kurzer ruhiger Halt.','Die Hand verlässt das Bild; Tageslicht übernimmt den Rand.'),
 (164.28,173.08,'3D','room','Die Nacht kippt','Vom Monitor weg öffnet sich erstmals der Blick ganz zum Fenster. Die Hausfassade gegenüber bekommt Konturen. Der Raum bleibt derselbe; die Kamera entdeckt jetzt, wie spät es geworden ist.','Eine langsame 90°-Schwenkfahrt vom Bildschirm zur Aussenwelt, kein Kamerawackeln.','Lichtstreifen auf Glas wird zur Kante der Kaffeetasse.'),
 (171.58,182.3,'3D','desk','Kalter Kaffee','Der Becher steht unbewegt. Die Oberfläche ist ruhig, Dampf ist nicht mehr vorhanden. Im Glas daneben liegt das helle Fenster. Im Hintergrund arbeitet der Bildschirm weiter.','85-mm-Makro, langsame Fokusfahrt von Tassenrand zu Fensterreflexion.','Der helle Reflex führt zurück auf eine neue Antwort.'),
 (175.12,185.66,'2D','screen','Eine Antwort, die man wirklich liest','Eine kurze Antwort mit genau einer Änderung und einem Testergebnis erscheint. Die Cursorposition wandert zeilenweise. Drei weitere UI-Flächen bleiben still; der Film gönnt dem Lesen Raum.','Orthogonal, breite Zeilenabstände, höchstens drei Zeilen gleichzeitig.','Unter der Antwort taucht die ursprüngliche Notiz wieder auf.'),
 (178.66,188.98,'hybrid','desk','Die gleiche kleine Bitte','Die Notiz vom Anfang liegt neben dem aktuellen Stand. Ihre Position stimmt mit S002 überein. Die Kamera zieht so weit zurück, dass die vielen erledigten Karten dahinter sichtbar werden.','50-mm-Zug rückwärts aus flacher UI in räumlichen Tisch; leichter Schatten macht den Übergang lesbar.','Die ursprüngliche Notiz bleibt vorne im Bild.'),
 (182.22,192.48,'3D','room','Ich bleib noch hier','Ein grosses, ruhiges Bild: heller werdendes Fenster, Person am Tisch, laufendes Projekt. Die Person richtet sich auf und bleibt. Der nächste Titel kündigt sich nur durch eine orange Kante am Monitor an.','Feste 35-mm-Halbtotale; sechs Sekunden dürfen ohne neuen Schnitt tragen.','Harter Wechsel von räumlicher Ruhe auf helle Typografie.'),
 (188.46,198.56,'2D','type','H05 · Tageslicht-Version','TOKEN BURN füllt das helle Bild. TOKEN ist jetzt tiefschwarz, BURN orange. Die Form ist dieselbe wie H01, die Wirkung grösser durch die Umkehr des Kontrasts. Der Fensterschatten läuft langsam unter der Schrift weiter.','Rein frontal und gross; kein Bloom auf der hellen Fläche.','Der Fensterschatten wird zur Trennlinie des Promptfelds.'),
 (191.68,201.7,'2D','screen','Noch immer ein Prompt','Die neue Eingabe erscheint auf der hellen Oberfläche. Ein kleiner Stapel erledigter Aufträge steht links; rechts bleibt Platz für genau die neue Zeile. Die Session ist produktiv und offen.','Frontal, gleiche Mittelachse wie S021, andere Helligkeit und grösserer sichtbarer Fortschritt.','Die Eingabe klappt nach hinten, der letzte grosse Titel bleibt vorn.'),
 (195.18,205.58,'hybrid','type','H06 · Das ganze Projekt dahinter','TOKEN BURN steht ein letztes Mal dominant in zwei Zeilen. In den Buchstaben ist kurz eine zusammenhängende Übersicht aller Projektstände zu sehen. Dann fahren die Buchstaben nach oben aus dem Bild und geben den fertigen aktuellen Stand frei.','Frontaler Titel; danach 35-mm-Rückfahrt, während die Schrift als lesbare Fläche aufrecht bleibt.','Die Projektübersicht füllt die freigegebene Bildfläche.'),
 (198.58,208.68,'3D','project','Alles ist derselbe Stand','Die Kamera streift am Export vorbei, passiert die gespeicherten Einstellungen und endet bei der laufenden Vorschau. Alle drei zeigen dieselbe Versionsnummer.','Kontinuierliche diagonale Fahrt mit drei klaren Stationen; keine neuen abstrakten Räume.','Die Versionsnummer wird zum aktiven Browser-Tab.'),
 (202.06,212.42,'2D','screen','Ein Tab zu, zwei offen','Der Tab-Wechsel wiederholt das bekannte Motiv exakt: einer schliesst, zwei kommen hinein. Diesmal stehen die neuen Tabs ruhig nebeneinander. Beide gehören zur nächsten Idee; der Verbrauchszähler läuft weiter.','Die Bewegung beginnt schnell und endet in vollständiger Ruhe.','Der rechte Tab reduziert sich auf eine einzelne Notiz.'),
 (205.54,216.04,'3D','desk','Nur dieser eine','Eine einzige Notiz liegt wieder vorne am Tisch. Hinter ihr liegen die vielen erledigten Karten aus der Nacht. Die Kamera fährt nach oben und zeigt den Unterschied zwischen dem kleinen neuen Wunsch und dem bereits gebauten Projekt.','Vertikaler Kran von 70-mm-Detail zur klaren Tischaufsicht, keine zusätzliche Drehung.','Die Aufsicht hält über den folgenden Instrumentaltakten.'),
 (209.98,218.42,'3D','room','Der fast fertige Abschied','Die Kamera fährt langsam aus dem Arbeitsplatz zurück. Die Hand bleibt einen Moment ganz still. Gerade als sich die Komposition wie ein Schlussbild anfühlt, bewegt sich der Cursor wieder.','Rückfahrt von Halbtotale zur Raumtotalen, dann Halt; die EN-Passage bekommt einen längeren Ruhepunkt.','Schnitt zurück auf den einen aktiven Cursor.'),
 (215.6,225.64,'2D','screen','Der letzte Auftrag steht bereit','Die neue Eingabe steht vollständig da: „Preset speichern“ / „Save a preset“. Der Sendeknopf ist noch unberührt. Im Hintergrund bleibt der gerade erreichte Stand sichtbar; es wird nichts zurückgesetzt.','Eine grosse ruhige Eingabefläche, Cursor am Ende, ausreichend Lesezeit.','Der Cursor bewegt sich zur Sendetaste und löst den nächsten Shot aus.'),
 (223.26,232.58,'hybrid','desk','SEND','Der Auftrag P06 wird abgesendet. SEND ist für einen kurzen Moment gross und prägnant, dann rückt die Schrift in den echten Knopf zurück. Die Kamera verlässt den Bildschirm und zeigt wieder die Hand am Trackpad.','Match Cut vom 2D-Knopf zum realen Trackpad; leichte 50-mm-Rückfahrt.','Die Bewegung geht ohne neuen Impuls in den Ausklang über.'),
 (227.84,234.34,'3D','room','Es läuft weiter','Der Bildschirm zeigt eine laufende Antwort. Die Person bleibt sitzen, die Kamera zieht rückwärts Richtung Fenster. Die neue Aufgabe wird bewusst noch nicht abgeschlossen.','35-mm-Rückfahrt auf dem umgekehrten Weg von S001, aber im Morgenlicht.','Der Fensterrahmen rahmt den Arbeitsplatz ein.'),
 (234,239.3,'3D','exterior','Dasselbe Fenster am Morgen','Die Kamera ist wieder vor der Fassade. Das zuvor einzige helle Fenster ist nun eines von vielen sichtbaren Fenstern im Tageslicht. Im eigenen Fenster bleibt der Cursor als kleiner Lichtpunkt erkennbar.','Langsamer gerader Rückzug; keine neue Stadtlandschaft, kein weiterer Titelblock.','Der Lichtpunkt bleibt bis zur gemessenen Schlussabnahme stehen.'),
 (240,244.8,'2D','end','Der Cursor bleibt zuletzt','Die Fassade und das Fenster gehen mit dem gemessenen Endabfall zurück. Ein kleiner Cursor bleibt kurz stehen und verschwindet erst am Audioende. Keine zusätzliche Schlussbehauptung, keine fertige Antwort.','Feste Komposition; globale Blende aus tatsächlichem Pegelverlauf mit monotonichem Endverschluss.','Schwarz exakt am Ende der jeweiligen WAV; letztes Rasterbild vollständig halten.'),
]

TRACKS = [('01_Vibecoder','VIBECODER','DE/EN Entwurf 0.1; Audio offen'), ('02_Token_Burn','TOKEN BURN','Drehbuch vorbereitet; DE und EN final'), ('03_SHIP_IT','SHIP IT','Drehbuch vorbereitet; DE und EN final'), ('04_AI_Slop','AI SLOP','Überarbeitung offen'), ('05_Hallucination','HALLUCINATION','Überarbeitung offen'), ('06_Context_Window','CONTEXT WINDOW','Überarbeitung offen')]
HOOKS = {
 'de':[(78.66,79.9,15),(85.74,87.02,17),(142.26,143.22,31),(149.42,150.34,32),(188.46,189.1,40),(195.18,196.52,42)],
 'en':[(96.48,97.58,15),(103.52,105.34,17),(153.0,153.72,29),(159.8,161.0,31),(198.56,199.24,39),(205.58,206.4,41)],
}

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write_json(path,data):
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2,allow_nan=False)+'\n')

def tc(t):
    ms=round(t*1000)
    return f'{ms//60000:02}:{ms//1000%60:02}.{ms%1000:03}'

def build():
    for folder,title,status in TRACKS:
        root=PACKAGE/folder
        for rel in ['assets/audio','assets/fonts','src/render','src/tools','output/qa','variants/de','variants/en']:
            (root/rel).mkdir(parents=True,exist_ok=True)
        if folder not in ('02_Token_Burn','03_SHIP_IT'):
            (root/'README.md').write_text(f'# {title}\n\nStatus: Platzhalter für die spätere Videoproduktion. Musikstand: {status}.\n\nQuelle im Musik-Repo: `../../../../music/kisound/Vibecoder/{folder}/`.\nKeine Zeitmarken, Audiozuordnung oder fertige Videoumsetzung festgelegt.\n\nVor dem Drehbuch: finale Sprachfassung wählen, zugehörige WAV und SHA-256 prüfen,\nTranskript und Audioanalyse erstellen beziehungsweise übernehmen. Beide\nSprachordner sind vorbereitet; ihre Existenz bedeutet keine Audiofreigabe.\n\n`src/render/` und `src/tools/` reservieren den bestehenden Codevideo-Aufbau;\n`assets/` und `output/qa/` bleiben bis zur Umsetzung leer.\n')
    manifest={'schema':'kisound.video.screenplay.sources.v1','album':'Vibecoder','track':'02_Token_Burn','intended_project_root':str(DESTINATION/'02_Token_Burn'),'path_base':'intended_project_root','fps':60,'variants':{}}
    global_shots=[]
    for index,row in enumerate(SHOTS):
        de,en,mode,zone,title,action,camera,transition=row
        global_shots.append({'id':f'S{index+1:03}','starts_s':{'de':de,'en':en},'mode':mode,'zone':zone,'title':title,'action':action,'camera':camera,'transition':transition})
    write_json(TRACK/'REGIE-CUES.json',{'schema':'kisound.video.screenplay.v1','status':'authored screenplay, not implemented','shots':global_shots})
    table=['# Schnittliste · TOKEN BURN','', '58 Einstellungen pro Fassung. Alle Start-/Endwerte sind absolute Sekunden ab WAV-Beginn.','Zeitmarken aus ASR bleiben vorläufig; zusätzliche Schnitte sind redaktionell.','', '| Shot | DE Start–Ende | EN Start–Ende | Raum / Modus | Handlung, Kamera und Übergang |','| --- | --- | --- | --- | --- |']
    durations={}
    for lang in ['de','en']:
        source=MUSIC_ALBUM/'02_Token_Burn'/'final'/lang
        variant=TRACK/'variants'/lang
        transcript=json.loads((source/'02_Token_Burn_Transkript.json').read_text())
        analysis=json.loads((source/'ASTRA-AUDIO-ANALYSE.json').read_text())
        duration=analysis['summary']['duration_s'];durations[lang]=duration
        inputs={}
        for key,filename in [('transcript','02_Token_Burn_Transkript.json'),('prompt','02_Token_Burn_1.0.txt'),('analysis','ASTRA-AUDIO-ANALYSE.json'),('review','TRANSKRIPT-PRUEFUNG.md')]:
            inputs[key]={'path':f'../../../../music/kisound/Vibecoder/02_Token_Burn/final/{lang}/{filename}','sha256':digest(source/filename)}
        wav=MUSIC_ALBUM/'02_Token_Burn'/'suno-0.1'/lang/f'Token Burn - {lang.upper()}.wav'
        inputs['audio']={'path':f'../../../../music/kisound/Vibecoder/02_Token_Burn/suno-0.1/{lang}/{wav.name}','sha256':digest(wav)}
        manifest['variants'][lang]={'duration_s':duration,'samples_per_channel':analysis['summary']['samples_per_channel'],'frames_60fps':math.ceil(duration*60),'inputs':inputs}
        for filename in ['ASTRA-AUDIO-ANALYSE.json','ASTRA-AUDIO-ANALYSE.md','ASTRA-AUDIO-ANALYSE.png','TRANSKRIPT-PRUEFUNG.md']:
            shutil.copy2(source/filename,variant/filename)
        shots=[]
        known_starts={s['start'] for s in transcript['segments']}
        for i,shot in enumerate(global_shots):
            start=shot['starts_s'][lang];end=global_shots[i+1]['starts_s'][lang] if i+1<len(global_shots) else duration
            lyrics=[{'id':s['id'],'start_s':s['start'],'end_s':s['end'],'text':s['text'],'review_required':s['review_required']} for s in transcript['segments'] if start<=s['start']<end]
            events=[e['id'] for e in analysis['events'] if start<=e['time_s']<end or i+1==len(global_shots) and e['time_s']==duration]
            shots.append({**{k:v for k,v in shot.items() if k!='starts_s'},'start_s':start,'end_s':end,'first_frame':math.ceil(start*60-1e-8),'end_frame_exclusive':math.ceil(end*60-1e-8),'start_origin':'ASR cue start, provisional' if start in known_starts else 'audio start' if start==0 else 'editorial cut; not a claimed word onset','lyrics_starting_here':lyrics,'analysis_event_ids':events})
        keywords=[]
        for i,(start,vocal_end,source_id) in enumerate(HOOKS[lang]):
            shot=next(s for s in shots if s['start_s']<=start<s['end_s'])
            cue=next(s for s in transcript['segments'] if s['id']==source_id)
            keywords.append({'id':f'H{i+1:02}','text':'TOKEN BURN','shot_id':shot['id'],'start_s':start,'vocal_end_s':vocal_end,'visual_end_s':round(min(shot['end_s']-.12,max(start+1.3,vocal_end+.25)),3),'source_segment_id':source_id,'source_text':cue['text'],'review_required':cue['review_required'],'timing_note':'DE H04: ASR-Unterfenster „tot Burn“ innerhalb Cue 32; prüfen' if lang=='de' and i==3 else 'Automatischer Wort-/Cue-Anker; Schreibweise aus finalem Tracktitel','treatment':['flat_dark','extrusion_reveal','room_type','split_plane','flat_daylight','project_inside_type'][i],'entry_s':.12,'exit_s':.18,'syllable_times_inferred':False})
        write_json(variant/'KEYWORDS.json',{'schema':'kisound.video.keywords.v1','language':lang,'audio_sha256':inputs['audio']['sha256'],'keywords':keywords})
        write_json(variant/'TIMELINE.json',{'schema':'kisound.video.timeline.v1','language':lang,'duration_s':duration,'fps':60,'frames':math.ceil(duration*60),'source_audio_sha256':inputs['audio']['sha256'],'transcript_sha256':inputs['transcript']['sha256'],'analysis_sha256':inputs['analysis']['sha256'],'shots':shots,'subtitles':{'default':'off','policy':'use original transcript cue times; never silently replace ASR text with prompt lyrics','review_report':'TRANSKRIPT-PRUEFUNG.md'}})
        lines=[f'# TOKEN BURN · {lang.upper()} · Zeitliste','',f'{duration:.6f} s · {math.ceil(duration*60)} Bilder bei 60 fps · 58 Einstellungen.','', 'Die Rohtexte dienen als Quellenbeleg. Unklare Zeilen werden im Hauptfilm durch die Bildhandlung getragen; vollständige Untertitel sind eine getrennte, zu prüfende Option.','', '| Shot | Zeit | Regie | Zugeordnete Lyrics / Ereignisse |','| --- | --- | --- | --- |']
        for s in shots:
            refs='; '.join(f'L{x["id"]:03} {x["text"]}'+(' **PRÜFEN**' if x['review_required'] else '') for x in s['lyrics_starting_here']) or 'Instrumental / Fortsetzung'
            refs+='; '+', '.join(s['analysis_event_ids']) if s['analysis_event_ids'] else ''
            lines.append(f'| {s["id"]} | {tc(s["start_s"])}–{tc(s["end_s"])} | **{s["title"]}** · {s["mode"]}. {s["action"]}<br>Kamera: {s["camera"]}<br>Übergang: {s["transition"]} | {refs} |')
        lines+=['','## TOKEN-BURN-Einsätze','','| Cue | Stimme | Bild bis | Quelle | Status |','| --- | --- | --- | --- | --- |']
        for k in keywords:lines.append(f'| {k["id"]} | {tc(k["start_s"])}–{tc(k["vocal_end_s"])} | {tc(k["visual_end_s"])} | L{k["source_segment_id"]:03} | '+('PRÜFEN' if k['review_required'] else 'ASR, nicht manuell bestätigt')+' |')
        (variant/'SHOTLIST.md').write_text('\n'.join(lines)+'\n')
    for i,s in enumerate(global_shots):
        end={lang:global_shots[i+1]['starts_s'][lang] if i+1<len(global_shots) else durations[lang] for lang in durations}
        table.append(f'| {s["id"]} | {tc(s["starts_s"]["de"])}–{tc(end["de"])} | {tc(s["starts_s"]["en"])}–{tc(end["en"])} | {s["zone"]} · {s["mode"]} | **{s["title"]}**. {s["action"]}<br>**Kamera:** {s["camera"]}<br>**Übergang:** {s["transition"]} |')
    (TRACK/'SCHNITTLISTE.md').write_text('\n'.join(table)+'\n')
    write_json(TRACK/'SOURCE-MANIFEST.json',manifest)
    summary={lang:{mode:round(sum(s['end_s']-s['start_s'] for s in json.loads((TRACK/'variants'/lang/'TIMELINE.json').read_text())['shots'] if s['mode']==mode),3) for mode in ['2D','3D','hybrid']} for lang in durations}
    print(json.dumps({'duration_s':durations,'screen_time_by_mode_s':summary},ensure_ascii=False,indent=2))

if __name__=='__main__':build()
